#include <stdio.h>
int main(){
	int n, m;
	scanf("%d%d", &n, &m);

	int a[100];
	for(int i=0; i<m; i++){
		scanf("%d", &a[i]);
	}

	int x[100][100];
	for(int i=0; i<n; i++){
		for(int j=0; j<m; j++){
			scanf("%d", &x[i][j]);
		}
	}

	for(int j=0; j<m; j++){
		// 栄養素 j について判定する
		int sum = 0;
		for(int i=0; i<n; i++){
			sum += x[i][j];
		}
		if(sum < a[j]){
			puts("No");
			return 0;
		}
	}

	puts("Yes");
}
